var e="November\xA02026",r="8be3b1d5",a="October\xA02026",o="Mohammad Almeqdadi, MD",t="https://qaddodi.github.io/#tools",s="mohammad.almeqdadi@gmail.com",i=["Healthy adult: portal pressure, HVPG, portal flow and cardiac output within normal ranges","Healthy: negligible collateral flow, no reversed portal vessels","Cirrhosis: HVPG rises monotonically; collateral recruitment begins near HVPG 10 mmHg","Presinusoidal disease: high portal pressure with a normal HVPG and no ascites","Right heart failure: high RAP and WHVP, normal HVPG, pulsatile portal vein, protein-rich ascites","Splenic vein thrombosis: normal portal pressure, high splenic vein pressure, flow through the short gastric veins","Splenorenal shunt in decompensated cirrhosis: the splenic vein reverses","End-stage cirrhosis with arterioportal shunting: hepatofugal portal flow","TIPS 10 mm at HVPG \u224820 mmHg: PPG <12 mmHg, shunt fraction and hepatic perfusion change as expected","Model calibration: no variceal rupture at an HVPG <12 mmHg (a simplification: real varices can bleed <12)","Hemorrhage lowers portal pressure; over-transfusion raises it above the pre-bleed level","BRTO of a gastrorenal shunt raises portal pressure by \u22652 mmHg","Nonselective \u03B2-blockers lower HVPG; carvedilol more than propranolol","Budd\u2013Chiari: caudate outflow \u22653\xD7 normal and ascites forms","Large-volume paracentesis lowers intra-abdominal and variceal transmural pressure","Blood volume is conserved without bleeding or infusion","Determinism: the same actions give an identical state","Stability at every slider extreme"];export{e as a,r as b,a as c,o as d,t as e,s as f,i as g};
